async function importFile(fixture,append=false,rejection=false){const before=await state(),noticeAt=await evaluate('window.__hostFiles.notice_events.length');if(append)await action('scene.append_obj');else await chord('o');const root=(await send('DOM.getDocument')).root,node=(await send('DOM.querySelector',{nodeId:root.nodeId,selector:'#import-file'})).nodeId;assert(node,'Normal import input missing');await send('DOM.setFileInputFiles',{nodeId:node,files:[fixture.path]});for(let i=0;i<120;i++){const s=await state(),notice=await evaluate('document.getElementById("notice").textContent');if(rejection&&notice&&(await evaluate('window.__hostFiles.notice_events.length'))>noticeAt){await pause(150);return {metrics:s,notice,notice_observations:await evaluate('window.__hostFiles.notice_events.slice('+noticeAt+')')};}if(!rejection&&notice)throw Error(notice);if(!rejection&&(append?s.subtools.length===before.subtools.length+1:s.vertices===fixture.expected.vertices)&&s.message.startsWith(append?'Appended ':'Loaded ')){await pause(180);return {metrics:s};}await pause(60);}throw Error('Normal file import/rejection timed out: '+fixture.path);}
async function loadBrushFixture(){await fresh();await importFile(sphere);const s=await state();assert(Math.fround(s.radius)===Math.fround(.18)&&Math.fround(s.strength)===Math.fround(.35)&&s.symmetry_x,'Actual default brush parameters differ');return s;}
async function backgroundFocus(){const s=await state(),r=s.camera.viewport;await click([r[2]-25,r[3]-25]);}
const brushes=[['Draw','1'],['Clay','2'],['Inflate','3'],['Smooth','4'],['Flatten','5'],['Crease','6'],['Move','7'],['Mask','8'],['Paint','9'],['Morph','0'],['Pinch','p'],['Twist','j'],['Local Scale','l'],['Drag','g']];
async function selectBrush(name){await backgroundFocus();await key(brushes.find(b=>b[0]===name)[1]);return waitFor(s=>s.kind===name,'Normal brush shortcut did not select '+name);}
function difference(a,b,field='positions'){const x=a[field],y=b[field];assert(y.length>=x.length,'Original vertex domain disappeared');let count=0,max=0,squared=0;for(let i=0;i<x.length;i++){const old=Array.isArray(x[i])?x[i]:[x[i]],now=Array.isArray(y[i])?y[i]:[y[i]];let sq=0;for(let c=0;c<old.length;c++){const d=Math.fround(now[c])-Math.fround(old[c]);sq+=d*d;}count+=Number(sq>0);max=Math.max(max,Math.sqrt(sq));squared+=sq;}return {changed:count,original_count:x.length,after_count:y.length,max,rms:Math.sqrt(squared/x.length)};}
function protectedPositions(a,b){return a.masks.every((v,i)=>Math.fround(v)!==1||a.positions[i].every((x,c)=>Object.is(Math.fround(x),Math.fround(b.positions[i][c]))));}
async function contact(mesh){const s=await state(),m=s.camera.view_projection,r=s.camera.viewport,eye=s.camera.position,normal=eye.map((x,i)=>x-s.camera.target[i]);const best=mesh.positions.reduce((winner,p)=>p.reduce((sum,x,i)=>sum+x*normal[i],0)>winner.reduce((sum,x,i)=>sum+x*normal[i],0)?p:winner);const clip=[0,1,2,3].map(i=>m[i]*best[0]+m[i+4]*best[1]+m[i+8]*best[2]+m[i+12]);assert(clip[3]>0,'Contact behind actual camera');return {point:best,screen:[r[0]+(r[2]-r[0])*(clip[0]/clip[3]+1)/2,r[1]+(r[3]-r[1])*(1-clip[1]/clip[3])/2].map(Math.round),camera:s.camera};}
async function quiet(stage){const probes=[];for(const delay of [0,200,800]){await pause(delay);const actual=await gpu(),sculpt=await evaluate('window.obrushSculptMetrics()');probes.push({requested_delay_ms:delay,at_epoch_ms:Date.now(),gpu:actual,sculpt});}const pass=probes.every(p=>p.gpu.sha256===probes[0].gpu.sha256&&p.sculpt.pending_dabs===0);result.release_quiet_observations??=[];result.release_quiet_observations.push({stage,probes,pass});await flush();assert(pass,'Geometry or pending dabs changed after release: '+stage);return {probes,pass};}
async function stroke(name,mesh,options={}){const queueBefore=await evaluate('window.obrushSculptMetrics()');const c=options.ray?await rayContact(mesh):await contact(mesh),center=c.screen,kind=(await state()).kind;let points;
  if(kind==='Twist')points=[[0,0],[32,0],[28,16],[16,28],[0,32],[-16,28],[-28,16],[-32,0]].map(p=>p.map((x,i)=>center[i]+x));
  else if(kind==='Local Scale')points=Array.from({length:9},(_,i)=>[center[0]+i*6,center[1]]);
  else if(options.fast)points=Array.from({length:81},(_,i)=>[center[0]+50*Math.sin(i*.15),center[1]+25*Math.cos(i*.15)]);
  else points=Array.from({length:9},(_,i)=>[center[0]+i*4,center[1]+3*Math.sin(i*.5)]);
  await pointer('mouseMoved',...points[0]);await pause(40);await pointer('mousePressed',...points[0],true);for(const p of points.slice(1)){await pointer('mouseMoved',...p,true);if(!options.fast)await pause(30);}await pointer('mouseReleased',...points.at(-1));await completion(name,(_s,q)=>q.released_strokes>queueBefore.released_strokes);const tail=await quiet(name),trial={name,kind,contact:c,input_points:points,spacing_ms:options.fast?0:30,tail};result.strokes.push(trial);return trial;
}
async function history(name,before,after){await chord('z');const undo=await snapshot(name+'-undo');await chord('z',true);const redo=await snapshot(name+'-redo');const checks={undo_exact:undo.record.sha256===before.record.sha256,redo_exact:redo.record.sha256===after.record.sha256};assert(Object.values(checks).every(Boolean),'Whole downloaded project history differs: '+name);return checks;}
async function finishCase(c){result.cases.push(c);await writeFile(path.join(out,c.name+'.case.json'),JSON.stringify(c,null,2)+'\n');await flush();console.log(JSON.stringify({completed:c.name,gates:c.gates}));assert(Object.values(c.gates).every(v=>v===true),'Failed declared host case: '+c.name);}


function inverseColumns(columns){
  const rows=Array.from({length:4},(_,r)=>[...Array.from({length:4},(_,c)=>columns[c*4+r]),...Array.from({length:4},(_,c)=>Number(c===r))]);
  for(let c=0;c<4;c++){let pivot=c;for(let r=c+1;r<4;r++)if(Math.abs(rows[r][c])>Math.abs(rows[pivot][c]))pivot=r;assert(Math.abs(rows[pivot][c])>1e-14,'Independent camera inverse is singular');[rows[c],rows[pivot]]=[rows[pivot],rows[c]];const scale=rows[c][c];rows[c]=rows[c].map(v=>v/scale);for(let r=0;r<4;r++)if(r!==c){const multiplier=rows[r][c];rows[r]=rows[r].map((v,i)=>v-multiplier*rows[c][i]);}}
  return rows.map(r=>r.slice(4));
}
async function rayContact(mesh){
  const camera=(await state()).camera,r=camera.viewport,inverse=inverseColumns(camera.view_projection),center=[(r[0]+r[2])/2,(r[1]+r[3])/2],points=[center];
  for(const fraction of [.12,.20,.28])for(const offset of [[fraction,0],[-fraction,0],[0,fraction],[0,-fraction]])points.push([center[0]+offset[0]*(r[2]-r[0]),center[1]+offset[1]*(r[3]-r[1])]);
  const faceScreens=[];for(const face of mesh.triangles){const p=[0,1,2].map(c=>face.reduce((sum,i)=>sum+Math.fround(mesh.positions[i][c])/3,0)),clip=[0,1,2,3].map(i=>camera.view_projection[i]*p[0]+camera.view_projection[i+4]*p[1]+camera.view_projection[i+8]*p[2]+camera.view_projection[i+12]);if(clip[3]<=0)continue;const screen=[r[0]+(r[2]-r[0])*(clip[0]/clip[3]+1)/2,r[1]+(r[3]-r[1])*(1-clip[1]/clip[3])/2];if(screen[0]>r[0]+45&&screen[0]<r[2]-45&&screen[1]>r[1]+45&&screen[1]<r[3]-45)faceScreens.push({screen,distance:Math.hypot(...screen.map((v,i)=>v-center[i]))});}faceScreens.sort((a,b)=>a.distance-b.distance);points.push(...faceScreens.slice(0,20).map(p=>p.screen));
  const subtract=(a,b)=>a.map((v,i)=>v-b[i]),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],dot=(a,b)=>a.reduce((n,v,i)=>n+v*b[i],0);
  for(const screen of points.map(p=>p.map(Math.round))){const xy=[2*(screen[0]-r[0])/(r[2]-r[0])-1,1-2*(screen[1]-r[1])/(r[3]-r[1])],unproject=z=>{const clip=[...xy,z,1],world=inverse.map(row=>row.reduce((n,v,i)=>n+v*clip[i],0));return world.slice(0,3).map(v=>v/world[3]);},origin=unproject(-1),far=unproject(1),direction=subtract(far,origin);let best=null;
    for(let face=0;face<mesh.triangles.length;face++){const [a,b,c]=mesh.triangles[face].map(i=>mesh.positions[i].map(Math.fround)),e1=subtract(b,a),e2=subtract(c,a),p=cross(direction,e2),det=dot(e1,p);if(Math.abs(det)<1e-12)continue;const tvec=subtract(origin,a),u=dot(tvec,p)/det;if(u<0||u>1)continue;const q=cross(tvec,e1),v=dot(direction,q)/det;if(v<0||u+v>1)continue;const t=dot(e2,q)/det;if(t>1e-9&&(!best||t<best.t))best={face,t,barycentric:[1-u-v,u,v],point:origin.map((x,i)=>x+t*direction[i])};}
    if(best)return {...best,screen,camera,oracle:'Independent f64 inverse view-projection + closest positive ray/triangle intersection; rendered data read-only'};
  }
  throw Error('No independent normal Draw contact on fresh primitive');
}

function readPngRgb(bytes){
  assert(bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])),'Actual screenshot is not PNG');let width,height,depth,color;const chunks=[];for(let at=8;at<bytes.length;){const length=bytes.readUInt32BE(at),kind=bytes.subarray(at+4,at+8).toString('ascii'),data=bytes.subarray(at+8,at+8+length);assert(at+length+12<=bytes.length,'Truncated screenshot PNG');assert(crc32(bytes.subarray(at+4,at+8+length))===bytes.readUInt32BE(at+8+length),'Screenshot PNG CRC differs');if(kind==='IHDR'){width=data.readUInt32BE(0);height=data.readUInt32BE(4);depth=data[8];color=data[9];assert(data[10]===0&&data[11]===0&&data[12]===0,'Unsupported screenshot PNG method/interlace');}if(kind==='IDAT')chunks.push(data);at+=length+12;if(kind==='IEND')break;}
  assert(depth===8&&[2,6].includes(color)&&width>0&&height>0&&width*height<=4_000_000,'Unsupported bounded screenshot PNG');const bpp=color===6?4:3,rowBytes=width*bpp,raw=inflateSync(Buffer.concat(chunks),{maxOutputLength:(rowBytes+1)*height}),decoded=Buffer.alloc(rowBytes*height),rgb=Buffer.alloc(width*height*3);assert(raw.length===(rowBytes+1)*height,'Screenshot decompressed length differs');const paeth=(a,b,c)=>{const p=a+b-c,da=Math.abs(p-a),db=Math.abs(p-b),dc=Math.abs(p-c);return da<=db&&da<=dc?a:db<=dc?b:c;};
  for(let y=0;y<height;y++){const filter=raw[y*(rowBytes+1)];assert(filter<=4,'Invalid PNG filter');for(let x=0;x<rowBytes;x++){const left=x>=bpp?decoded[y*rowBytes+x-bpp]:0,above=y>0?decoded[(y-1)*rowBytes+x]:0,upperLeft=y>0&&x>=bpp?decoded[(y-1)*rowBytes+x-bpp]:0,add=[0,left,above,Math.floor((left+above)/2),paeth(left,above,upperLeft)][filter];decoded[y*rowBytes+x]=(raw[y*(rowBytes+1)+1+x]+add)&255;}for(let x=0;x<width;x++)for(let c=0;c<3;c++)rgb[(y*width+x)*3+c]=decoded[y*rowBytes+x*bpp+c];}
  return {width,height,rgb};
}
async function viewportImage(stage){const s=await state(),r=s.camera.viewport,clip={x:Math.ceil(r[0]+8),y:Math.ceil(r[1]+8),width:Math.floor(r[2]-r[0]-16),height:Math.floor(r[3]-r[1]-16),scale:1};assert(s.ui_zoom_factor===1,'Viewport crop requires actual default Egui UI scale');await pause(180);const shot=await send('Page.captureScreenshot',{format:'png',fromSurface:true,clip}),bytes=Buffer.from(shot.data,'base64'),file=path.join(out,stage+'-viewport.png');await writeFile(file,bytes);const record={path:file,bytes:bytes.length,sha256:hash(bytes),clip,camera:s.camera,metrics:s};result.screenshots.push(record);const decoded=readPngRgb(bytes);return {record,decoded};}
function pixelDifference(a,b){assert(a.width===b.width&&a.height===b.height,'Viewport screenshot dimensions differ');let changed=0,max=0,squared=0;for(let p=0;p<a.width*a.height;p++){let any=false;for(let c=0;c<3;c++){const d=Math.abs(a.rgb[p*3+c]-b.rgb[p*3+c]);any||=d>=2;max=Math.max(max,d);squared+=d*d;}changed+=Number(any);}const rms=Math.sqrt(squared/(a.rgb.length));return {width:a.width,height:a.height,pixels:a.width*a.height,changed_pixels_by_at_least2:changed,maximum_channel_difference:max,rms_rgb_0_255:rms,gate:changed>=1000&&max>=3&&rms>=.5};}

const materialValues=mesh=>mesh.materials??mesh.positions.map(()=>[Math.fround(.18),Math.fround(.08)]);
const geometryFixed=(a,b)=>floatChannelsEqual(a.positions,b.positions)&&floatChannelsEqual(a.normals,b.normals)&&floatChannelsEqual(a.masks,b.masks)&&packedIndices(a)===packedIndices(b)&&JSON.stringify(a.surface??null)===JSON.stringify(b.surface??null);
function paintDelta(a,b){const ma=materialValues(a),mb=materialValues(b);return {rgb:difference(a,b,'colors'),roughness:difference({positions:ma.map(v=>[v[0]])},{positions:mb.map(v=>[v[0]])}),metallic:difference({positions:ma.map(v=>[v[1]])},{positions:mb.map(v=>[v[1]])})};}
function maskedPaintExact(a,b){const ma=materialValues(a),mb=materialValues(b);return a.masks.every((weight,i)=>Math.fround(weight)!==1||floatChannelsEqual(a.colors[i],b.colors[i])&&floatChannelsEqual(ma[i],mb[i]));}
async function paintConfig(rgb,rough,metal){await selectBrush('Paint');await enable('settings.paint_rgb','paint_rgb',rgb);await enable('settings.paint_roughness','paint_roughness',rough);await enable('settings.paint_metallic','paint_metallic',metal);await sliderEndpoint('settings.roughness','roughness',1);await sliderEndpoint('settings.metallic','metallic',0);return state();}
async function vertexDisplay(value){const before=await gpu();if(before.draws.some(d=>d.use_vertex_color!==value))await action('viewport.show_vertex_color');const after=await gpu();assert(after.draws.every(d=>d.use_vertex_color===value),'Actual vertex RGB display checkbox/uniform differs');return after;}

async function loadAttributeFixture(f){await fresh();await importFile(f);await selectBrush('Draw');const s=await state();assert(Math.fround(s.radius)===Math.fround(.18)&&Math.fround(s.strength)===Math.fround(.35),'Attribute fixture default brush settings differ');return s;}
function metadataExact(a,b){return JSON.stringify(a.surface??null)===JSON.stringify(b.surface??null)&&floatChannelsEqual(a.materials??[],b.materials??[]);}

