const preferenceInputInstrument=`(()=>{const p=window.__preferenceInput={events:[]};for(const type of ['pointerdown','pointermove','pointerup','keydown','keyup'])window.addEventListener(type,e=>p.events.push({type,key:e.key??null,buttons:e.buttons??null,x:e.clientX??null,y:e.clientY??null,shift:e.shiftKey,ctrl:e.ctrlKey,alt:e.altKey,trusted:e.isTrusted,scene_frame_at:window.__brushCheck?.scene_frame?.at??null,at:performance.now()}),{capture:true,passive:true});})();`;
function toolRow(s,kind=s.kind){const row=s.preferences?.tools?.find(t=>t.kind===kind);assert(row,'Registered preferences row missing: '+kind);return row;}
function viewFields(s){return {kind:s.kind,radius:s.radius,strength:s.strength,invert:s.invert,color:s.paint_color,screen_space_radius:s.screen_space_radius,screen_radius_pixels:s.screen_radius_pixels,lock_position:s.lock_position,paint_rgb:s.paint_rgb,paint_roughness:s.paint_roughness,paint_metallic:s.paint_metallic,roughness:s.roughness,metallic:s.metallic};}
function exactPreferenceFields(a,b){for(const key of ['radius','strength','screen_radius_pixels','roughness','metallic'])if(!Object.is(Math.fround(a[key]),Math.fround(b[key])))return false;return ['kind','invert','screen_space_radius','lock_position','paint_rgb','paint_roughness','paint_metallic'].every(key=>a[key]===b[key])&&floatChannelsEqual(a.color,b.color);}
function rowsExact(a,b){return a.length===b.length&&a.every((row,i)=>exactPreferenceFields(row,b[i])&&row.alpha===b[i].alpha);}
async function tile(kind){await action('brush.'+kind.toLowerCase().replaceAll(' ','_'));return waitFor(s=>s.kind===kind&&s.preferences.selected===kind,'Normal tile did not select '+kind);}
