async function currentToolMatches(expected,method){const s=await state(),row=toolRow(s);assert(exactPreferenceFields(viewFields(s),expected)&&exactPreferenceFields(row,expected)&&row.alpha===expected.alpha,'Tool preferences changed after '+method+': '+expected.kind);return {method,view:viewFields(s),saved:row,preferences_revision:s.preferences.revision};}
